type ChartExecutionQuote = {
  paneId: string;
  symbol: string;
  source: "live" | "replay";
  bid: number;
  ask: number;
  mid: number;
  /**
   * The price this packet TRADED at, when it carried a print.
   *
   * Resting orders and TP/SL are levels in the book, and a level is hit by
   * what trades, not by where the touch sits. Without this the engine only
   * saw the best bid/ask and a tapped level never filled.
   */
  last?: number;
  timestamp: number;
  receivedAt: number;
};

const liveExecutionQuotesBySymbol = new Map<string, ChartExecutionQuote>();
const liveExecutionQuoteSubscribers = new Set<() => void>();
let liveExecutionQuoteNotifyFrame: number | null = null;

function publishLiveExecutionQuote(quote: ChartExecutionQuote) {
  const key = normalizePaperSymbol(quote.symbol);
  const previous = liveExecutionQuotesBySymbol.get(key);
  const previousIsStillArriving = previous
    && previous.source === quote.source
    && quote.receivedAt - previous.receivedAt < 5_000;

  // Several panes can display the same contract and therefore receive the
  // same shared market packet. Keep one monotonic mark per symbol so a slower
  // background pane cannot overwrite the live P&L with an older quote. After
  // a genuine reconnect gap, allow the new stream to establish its watermark
  // even if its provider timestamp restarted slightly behind the old stream.
  if (
    previous
    && previousIsStillArriving
    && (
      quote.timestamp < previous.timestamp
      || (
        quote.timestamp === previous.timestamp
        && quote.bid === previous.bid
        && quote.ask === previous.ask
        && quote.mid === previous.mid
      )
    )
  ) return false;

  liveExecutionQuotesBySymbol.set(key, quote);
  if (liveExecutionQuoteNotifyFrame !== null) return true;
  liveExecutionQuoteNotifyFrame = window.requestAnimationFrame(() => {
    liveExecutionQuoteNotifyFrame = null;
    liveExecutionQuoteSubscribers.forEach((notify) => notify());
  });
  return true;
}

function subscribeLiveExecutionQuote(notify: () => void) {
  liveExecutionQuoteSubscribers.add(notify);
  notify();
  return () => {
    liveExecutionQuoteSubscribers.delete(notify);
  };
}

function useLiveExecutionQuoteFeed() {
  const [, setVersion] = useState(0);
  useEffect(() => subscribeLiveExecutionQuote(() => setVersion((version) => version + 1)), []);
  return liveExecutionQuotesBySymbol;
}

function livePaperPositionMark(
  position: PaperPosition,
  quotesBySymbol: ReadonlyMap<string, ChartExecutionQuote>,
) {
  const quote = quotesBySymbol.get(normalizePaperSymbol(position.symbol)) ?? null;
  return paperPositionMarkPrice(position, quote ? { ...quote, timestamp: quote.receivedAt } : null);
}

function livePaperPositionPnl(
  position: PaperPosition,
  quotesBySymbol: ReadonlyMap<string, ChartExecutionQuote>,
) {
  const quote = quotesBySymbol.get(normalizePaperSymbol(position.symbol)) ?? null;
  return paperPositionLivePnl(position, quote ? { ...quote, timestamp: quote.receivedAt } : null);
}

function LivePaperPositionPnl({ position }: { position: PaperPosition }) {
  const quotesBySymbol = useLiveExecutionQuoteFeed();
  const pnl = livePaperPositionPnl(position, quotesBySymbol);
  return (
    <span className={`font-mono text-[11px] tabular-nums ${pnl >= 0 ? "text-primary" : "text-danger"}`}>
      {pnl > 0 ? "+" : pnl < 0 ? "-" : ""}{formatDollar(pnl)}
    </span>
  );
}

function LivePaperPositionMark({ position }: { position: PaperPosition }) {
  const quotesBySymbol = useLiveExecutionQuoteFeed();
  return <span>Mark {formatPrice(livePaperPositionMark(position, quotesBySymbol), position.symbol)}</span>;
}

function LivePaperOpenPnl({ positions }: { positions: PaperPosition[] }) {
  const quotesBySymbol = useLiveExecutionQuoteFeed();
  const pnl = positions.reduce((sum, position) => sum + livePaperPositionPnl(position, quotesBySymbol), 0);
  return (
    <span className={`font-mono text-[13px] font-semibold tabular-nums ${pnl > 0 ? "text-primary" : pnl < 0 ? "text-danger" : "text-foreground"}`}>
      {pnl > 0 ? "+" : pnl < 0 ? "-" : ""}{formatDollar(pnl)}
    </span>
  );
}

function paperLedgerExecutionShapeChanged(
  previous: PaperTradingLedger,
  next: PaperTradingLedger,
) {
  const accountIds = new Set([
    ...Object.keys(previous.accounts),
    ...Object.keys(next.accounts),
  ]);
  for (const accountId of accountIds) {
    const before = previous.accounts[accountId];
    const after = next.accounts[accountId];
    if (!before || !after) return true;
    if (
      before.cashBalance !== after.cashBalance
      || before.realizedPnl !== after.realizedPnl
      || before.fills.length !== after.fills.length
      || before.orders.length !== after.orders.length
      || before.positions.length !== after.positions.length
    ) return true;
    for (let index = 0; index < before.orders.length; index += 1) {
      const left = before.orders[index];
      const right = after.orders[index];
      if (!right || left.id !== right.id || left.status !== right.status) return true;
    }
    for (let index = 0; index < before.positions.length; index += 1) {
      const left = before.positions[index];
      const right = after.positions[index];
      if (
        !right
        || left.id !== right.id
        || left.status !== right.status
        || left.remainingQuantity !== right.remainingQuantity
      ) return true;
    }
  }
  return false;
}

const liveWatchlistSnapshots = new Map<string, LiveWatchlistSnapshot>();
const liveWatchlistSubscribers = new Map<string, Set<() => void>>();
const dirtyLiveWatchlistKeys = new Set<string>();
let liveWatchlistNotifyFrame: number | null = null;
const liveWatchlistFlashTimers = new Map<string, ReturnType<typeof setTimeout>>();

function scheduleLiveWatchlistPaint(key: string) {
  dirtyLiveWatchlistKeys.add(key);
  if (liveWatchlistNotifyFrame !== null) return;
  liveWatchlistNotifyFrame = window.requestAnimationFrame(() => {
    liveWatchlistNotifyFrame = null;
    const keys = [...dirtyLiveWatchlistKeys];
    dirtyLiveWatchlistKeys.clear();
    for (const dirtyKey of keys) {
      liveWatchlistSubscribers.get(dirtyKey)?.forEach((notify) => notify());
    }
  });
}

function publishLiveWatchlistQuote(
  key: string,
  quote: LiveFeedPrice,
  fallbackOpenPrice = 0,
) {
  const previous = liveWatchlistSnapshots.get(key);
  const mid = Number(quote.mid);
  if (!Number.isFinite(mid) || mid <= 0) return;
  const previousMid = previous?.mid || mid;
  const openPrice = previous?.openPrice || fallbackOpenPrice || mid;
  const change = mid - openPrice;
  liveWatchlistSnapshots.set(key, {
    lastPrice: mid,
    openPrice,
    bid: Number.isFinite(Number(quote.bid)) ? Number(quote.bid) : mid,
    ask: Number.isFinite(Number(quote.ask)) ? Number(quote.ask) : mid,
    mid,
    change,
    changePercent: openPrice ? (change / openPrice) * 100 : 0,
    flash: mid > previousMid ? "up" : mid < previousMid ? "down" : previous?.flash ?? null,
  });

  const previousFlashTimer = liveWatchlistFlashTimers.get(key);
  if (previousFlashTimer) clearTimeout(previousFlashTimer);
  liveWatchlistFlashTimers.set(key, setTimeout(() => {
    liveWatchlistFlashTimers.delete(key);
    const current = liveWatchlistSnapshots.get(key);
    if (!current?.flash) return;
    liveWatchlistSnapshots.set(key, { ...current, flash: null });
    scheduleLiveWatchlistPaint(key);
  }, 600));

  // Paint the small watchlist cells independently of the workspace shell at
  // the display's native refresh cadence. One shared frame fans out every
  // dirty symbol, so 60/120/144 Hz screens remain smooth without creating one
  // React render or animation callback per CME packet.
  scheduleLiveWatchlistPaint(key);
}

function subscribeLiveWatchlistQuote(key: string, notify: () => void) {
  const subscribers = liveWatchlistSubscribers.get(key) ?? new Set<() => void>();
  subscribers.add(notify);
  liveWatchlistSubscribers.set(key, subscribers);
  notify();
  return () => {
    subscribers.delete(notify);
    if (!subscribers.size) liveWatchlistSubscribers.delete(key);
  };
}
