    const source = String(classicGexSettings.mappingSource ?? "QQQ") === "NDX" ? "NDX" : "QQQ";
    const expiry = ["ZERO_DTE", "NEXT_EXPIRY", "ALL"].includes(String(classicGexSettings.expiry))
