                  <span className="grid h-4 w-4 grid-cols-3 gap-px">
                    <span className="rounded-[1px] border border-current/70 bg-current/15" />
                    <span className="rounded-[1px] border border-current/70 bg-current/15" />
                    <span className="rounded-[1px] border border-current/70 bg-current/15" />
                  </span>
